// LoadRoleNameRole loads the userRole's RoleNameRole into the .R struct
func (os UserRoleSlice) LoadRoleNameRole(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	roles, err := os.RoleNameRole(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.RoleNameRole = nil
		o.R.Loaded.RoleNameRole = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	userRoleByKey := make(map[string][]*UserRole, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		userRoleByKey[o.RoleName] = append(userRoleByKey[o.RoleName], o)
	}

	for _, rel := range roles {

		owners, ok := userRoleByKey[rel.Name]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.RoleNameRole != nil {
				continue
			}

			o.R.RoleNameRole = rel

		}
	}

	return nil
}

